-- LemmaYard problem catalog for Supabase (SQL Editor -> New query -> paste -> Run).
-- Generated by `pnpm problems:export-sql` from problems/*; do not edit by hand.
-- Contains 50 problems, 25 tags and 6625 test cases. Run it after
-- docs/supabase/schema.sql (or `pnpm db:migrate`). It writes the same rows as
-- `pnpm problems:import`: upsert by slug (published), tags, and a full
-- replacement of each problem's tags and test cases, in one transaction.
-- Safe to run again; it never unpublishes problems that are not listed here.
-- NOTE: this file contains the HIDDEN test cases too (is_sample = false). They are
-- public anyway, because problems/*/tests.json is committed to this repository.

BEGIN;

-- Refuse to run if another problem in the database already uses one of these numbers.
DO $$
DECLARE taken text;
BEGIN
  SELECT string_agg("slug" || ' (' || "number" || ')', ', ') INTO taken
  FROM "problems"
  WHERE "number" IN (26, 27, 31, 36, 41, 50, 5, 6, 32, 49, 10, 14, 3, 29, 38, 19, 33, 23, 8, 39, 45, 13, 37, 46, 34, 17, 15, 20, 22, 11, 12, 47, 30, 9, 42, 16, 28, 44, 7, 25, 21, 40, 43, 35, 24, 48, 18, 1, 4, 2)
    AND "slug" NOT IN ($ly$alarm-streak$ly$, $ly$anagram-families$ly$, $ly$back-to-back-talks$ly$, $ly$balanced-vote-stretches$ly$, $ly$banner-widths$ly$, $ly$best-hub-town$ly$, $ly$best-time-to-buy-and-sell-stock$ly$, $ly$binary-search$ly$, $ly$busiest-moment$ly$, $ly$checkpoint-tour$ly$, $ly$climbing-stairs$ly$, $ly$coin-change$ly$, $ly$contains-duplicate$ly$, $ly$deepest-bracket-nesting$ly$, $ly$earliest-free-server$ly$, $ly$edit-distance$ly$, $ly$even-bit-xor-pairs$ly$, $ly$first-overdraft-day$ly$, $ly$fizz-buzz$ly$, $ly$growing-clubs$ly$, $ly$guarded-queens$ly$, $ly$house-robber$ly$, $ly$knight-through-walls$ly$, $ly$ladder-word-routes$ly$, $ly$largest-island-coastline$ly$, $ly$longest-common-subsequence$ly$, $ly$longest-substring-without-repeating-characters$ly$, $ly$longest-valid-parentheses$ly$, $ly$lucky-digit-sums$ly$, $ly$maximum-subarray$ly$, $ly$merge-intervals$ly$, $ly$ore-pile-merging$ly$, $ly$pair-sum-under-cap$ly$, $ly$palindrome-number$ly$, $ly$prefix-favorites$ly$, $ly$product-of-array-except-self$ly$, $ly$range-count-queries$ly$, $ly$rating-upsets$ly$, $ly$reverse-string$ly$, $ly$reversed-twins$ly$, $ly$sensor-spikes$ly$, $ly$shortest-full-playlist$ly$, $ly$smallest-task-order$ly$, $ly$spaced-harvest$ly$, $ly$squeeze-repeats$ly$, $ly$toll-free-passes$ly$, $ly$trapping-rain-water$ly$, $ly$two-sum$ly$, $ly$valid-anagram$ly$, $ly$valid-parentheses$ly$);
  IF taken IS NOT NULL THEN
    RAISE EXCEPTION 'problem numbers already used by other problems in the database: %', taken;
  END IF;
END $$;

-- Park the numbers of existing rows so renumbering between them cannot collide;
-- every parked row gets its real number back from the upserts below.
UPDATE "problems" SET "number" = "number" + 1000000000
WHERE "slug" IN ($ly$alarm-streak$ly$, $ly$anagram-families$ly$, $ly$back-to-back-talks$ly$, $ly$balanced-vote-stretches$ly$, $ly$banner-widths$ly$, $ly$best-hub-town$ly$, $ly$best-time-to-buy-and-sell-stock$ly$, $ly$binary-search$ly$, $ly$busiest-moment$ly$, $ly$checkpoint-tour$ly$, $ly$climbing-stairs$ly$, $ly$coin-change$ly$, $ly$contains-duplicate$ly$, $ly$deepest-bracket-nesting$ly$, $ly$earliest-free-server$ly$, $ly$edit-distance$ly$, $ly$even-bit-xor-pairs$ly$, $ly$first-overdraft-day$ly$, $ly$fizz-buzz$ly$, $ly$growing-clubs$ly$, $ly$guarded-queens$ly$, $ly$house-robber$ly$, $ly$knight-through-walls$ly$, $ly$ladder-word-routes$ly$, $ly$largest-island-coastline$ly$, $ly$longest-common-subsequence$ly$, $ly$longest-substring-without-repeating-characters$ly$, $ly$longest-valid-parentheses$ly$, $ly$lucky-digit-sums$ly$, $ly$maximum-subarray$ly$, $ly$merge-intervals$ly$, $ly$ore-pile-merging$ly$, $ly$pair-sum-under-cap$ly$, $ly$palindrome-number$ly$, $ly$prefix-favorites$ly$, $ly$product-of-array-except-self$ly$, $ly$range-count-queries$ly$, $ly$rating-upsets$ly$, $ly$reverse-string$ly$, $ly$reversed-twins$ly$, $ly$sensor-spikes$ly$, $ly$shortest-full-playlist$ly$, $ly$smallest-task-order$ly$, $ly$spaced-harvest$ly$, $ly$squeeze-repeats$ly$, $ly$toll-free-passes$ly$, $ly$trapping-rain-water$ly$, $ly$two-sum$ly$, $ly$valid-anagram$ly$, $ly$valid-parentheses$ly$);

