-- ---- valid-anagram ----
INSERT INTO "problems" ("number", "slug", "title", "difficulty", "description_md", "signature", "compare", "time_limit_ms", "memory_limit_mb", "published", "author_rating")
VALUES (4, $ly$valid-anagram$ly$, $ly$Valid Anagram$ly$, $ly$easy$ly$, $ly$Two words are anagrams of each other when one can be turned into the other just
by reordering its letters: both use the same letters, each the same number of
times.

Given two strings `s` and `t`, return `true` if `t` is an anagram of `s`, and
`false` otherwise. A string is an anagram of itself.

## Constraints

- `1 <= s.length, t.length <= 10^4`
- `s` and `t` contain only lowercase English letters `a`-`z`.
- The two strings may have different lengths.
$ly$, $ly${"name":"isAnagram","params":[{"name":"s","type":"string"},{"name":"t","type":"string"}],"returns":"bool"}$ly$::jsonb, $ly${"mode":"exact"}$ly$::jsonb, 2000, 256, TRUE, 1150)
ON CONFLICT ("slug") DO UPDATE SET
  "number" = EXCLUDED."number",
  "slug" = EXCLUDED."slug",
  "title" = EXCLUDED."title",
  "difficulty" = EXCLUDED."difficulty",
  "description_md" = EXCLUDED."description_md",
  "signature" = EXCLUDED."signature",
  "compare" = EXCLUDED."compare",
  "time_limit_ms" = EXCLUDED."time_limit_ms",
  "memory_limit_mb" = EXCLUDED."memory_limit_mb",
  "published" = EXCLUDED."published",
  "author_rating" = EXCLUDED."author_rating",
  "updated_at" = now();

DELETE FROM "problem_tags" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$valid-anagram$ly$);
INSERT INTO "problem_tags" ("problem_id", "tag_id")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$valid-anagram$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$string$ly$, $ly$hash-table$ly$);

DELETE FROM "test_cases" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$valid-anagram$ly$);
INSERT INTO "test_cases" ("problem_id", "position", "input", "expected", "is_sample")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$valid-anagram$ly$), v.* FROM (VALUES
  (0, $ly${"s":"listen","t":"silent"}$ly$::jsonb, $ly$true$ly$::jsonb, TRUE),
  (1, $ly${"s":"apple","t":"paper"}$ly$::jsonb, $ly$false$ly$::jsonb, TRUE),
  (2, $ly${"s":"a","t":"a"}$ly$::jsonb, $ly$true$ly$::jsonb, FALSE),
  (3, $ly${"s":"a","t":"b"}$ly$::jsonb, $ly$false$ly$::jsonb, FALSE),
  (4, $ly${"s":"ab","t":"a"}$ly$::jsonb, $ly$false$ly$::jsonb, FALSE),
  (5, $ly${"s":"aabb","t":"abab"}$ly$::jsonb, $ly$true$ly$::jsonb, FALSE),
  (6, $ly${"s":"aab","t":"abb"}$ly$::jsonb, $ly$false$ly$::jsonb, FALSE),
  (7, $ly${"s":"zzzz","t":"zzz"}$ly$::jsonb, $ly$false$ly$::jsonb, FALSE),
  (8, $ly${"s":"dormitory","t":"dirtyroom"}$ly$::jsonb, $ly$true$ly$::jsonb, FALSE),
  (9, $ly${"s":"abcdefghijklmnopqrstuvwxyz","t":"zyxwvutsrqponmlkjihgfedcba"}$ly$::jsonb, $ly$true$ly$::jsonb, FALSE),
  (10, $ly${"s":"","t":""}$ly$::jsonb, $ly$true$ly$::jsonb, FALSE),
  (11, $ly${"s":"","t":""}$ly$::jsonb, $ly$false$ly$::jsonb, FALSE)
) AS v ("position", "input", "expected", "is_sample")
ORDER BY v."position";

-- ---- valid-parentheses ----
INSERT INTO "problems" ("number", "slug", "title", "difficulty", "description_md", "signature", "compare", "time_limit_ms", "memory_limit_mb", "published", "author_rating")
VALUES (2, $ly$valid-parentheses$ly$, $ly$Valid Parentheses$ly$, $ly$easy$ly$, $ly$A string `s` is made only of the bracket characters `(`, `)`, `[`, `]`, `{` and
`}`. Decide whether the brackets in it are balanced, and return `true` if they
are, `false` otherwise.

The brackets are balanced when:

- every opening bracket is eventually closed by a bracket of the same kind;
- brackets close in reverse order of opening, so an inner pair must be closed
  before the pair around it;
- no closing bracket appears without a matching opening bracket before it.

The empty string counts as balanced.

## Constraints

- `0 <= s.length <= 10^4`
- `s` contains only the characters `()[]{}`.
$ly$, $ly${"name":"isValid","params":[{"name":"s","type":"string"}],"returns":"bool"}$ly$::jsonb, $ly${"mode":"exact"}$ly$::jsonb, 2000, 256, TRUE, 1270)
ON CONFLICT ("slug") DO UPDATE SET
  "number" = EXCLUDED."number",
  "slug" = EXCLUDED."slug",
  "title" = EXCLUDED."title",
  "difficulty" = EXCLUDED."difficulty",
  "description_md" = EXCLUDED."description_md",
  "signature" = EXCLUDED."signature",
  "compare" = EXCLUDED."compare",
  "time_limit_ms" = EXCLUDED."time_limit_ms",
  "memory_limit_mb" = EXCLUDED."memory_limit_mb",
  "published" = EXCLUDED."published",
  "author_rating" = EXCLUDED."author_rating",
  "updated_at" = now();

DELETE FROM "problem_tags" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$valid-parentheses$ly$);
INSERT INTO "problem_tags" ("problem_id", "tag_id")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$valid-parentheses$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$string$ly$, $ly$stack$ly$);

DELETE FROM "test_cases" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$valid-parentheses$ly$);
INSERT INTO "test_cases" ("problem_id", "position", "input", "expected", "is_sample")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$valid-parentheses$ly$), v.* FROM (VALUES
  (0, $ly${"s":"()"}$ly$::jsonb, $ly$true$ly$::jsonb, TRUE),
  (1, $ly${"s":"([]{})"}$ly$::jsonb, $ly$true$ly$::jsonb, TRUE),
  (2, $ly${"s":"{)"}$ly$::jsonb, $ly$false$ly$::jsonb, TRUE),
  (3, $ly${"s":""}$ly$::jsonb, $ly$true$ly$::jsonb, FALSE),
  (4, $ly${"s":"("}$ly$::jsonb, $ly$false$ly$::jsonb, FALSE),
  (5, $ly${"s":"}"}$ly$::jsonb, $ly$false$ly$::jsonb, FALSE),
  (6, $ly${"s":"{(})"}$ly$::jsonb, $ly$false$ly$::jsonb, FALSE),
  (7, $ly${"s":"{[()()]}"}$ly$::jsonb, $ly$true$ly$::jsonb, FALSE),
  (8, $ly${"s":"[](){}"}$ly$::jsonb, $ly$true$ly$::jsonb, FALSE),
  (9, $ly${"s":"))(("}$ly$::jsonb, $ly$false$ly$::jsonb, FALSE),
  (10, $ly${"s":"(((((("}$ly$::jsonb, $ly$false$ly$::jsonb, FALSE),
  (11, $ly${"s":"{{}}[[]]((]]"}$ly$::jsonb, $ly$false$ly$::jsonb, FALSE),
